"""matplotlib.contour — contour plot classes."""

import sys as _sys

from matplotlib.artist import Artist
import numpy as _np


_contour_warned = set()

def _contour_getattr_fallback(self, name):
    if name.startswith('_'):
        raise AttributeError(name)
    key = f'{type(self).__name__}.{name}'
    if key not in _contour_warned:
        _contour_warned.add(key)
        try:
            _sys.__stderr__.write(
                f"[mpl-shim] contour.{key}() not implemented — returning None\n")
        except Exception:
            pass
    def _noop(*args, **kwargs): return None
    return _noop


class ContourSet(Artist):
    __getattr__ = _contour_getattr_fallback

    def __init__(self, ax=None, *args, **kwargs):
        super().__init__()
        self.ax = ax
        self.axes = ax
        self.levels = list(kwargs.get('levels') or [])
        self.collections = []
        self.allsegs = []
        self.allkinds = []
        self.cvalues = list(kwargs.get('levels') or [])
        self.layers = self.cvalues
        self.cmap = kwargs.get('cmap', None)
        self.norm = kwargs.get('norm', None)
        self.colors = kwargs.get('colors', None)
        self.linewidths = kwargs.get('linewidths', None)
        self.linestyles = kwargs.get('linestyles', None)
        self.alpha = kwargs.get('alpha', None)
        self.filled = kwargs.get('filled', False)
        self.extend = kwargs.get('extend', 'neither')
        self.antialiased = kwargs.get('antialiased', None)
        self.zorder = kwargs.get('zorder', 1)
        self.labelTexts = []
        self.labelCValues = []
        self.labelLevelList = []

    def clabel(self, levels=None, **kwargs):
        return []

    def changed(self):
        pass
    def get_array(self):
        return _np.array(self.cvalues)
    def set_array(self, A):
        if A is not None: self.cvalues = list(A)
    def set_alpha(self, a):  self.alpha = a
    def get_alpha(self):     return self.alpha
    def set_cmap(self, c):   self.cmap = c
    def get_cmap(self):      return self.cmap
    def set_clim(self, vmin=None, vmax=None):
        self._clim = (vmin, vmax)
    def get_clim(self):      return getattr(self, '_clim', (None, None))
    def set_norm(self, n):   self.norm = n
    def get_norm(self):      return self.norm
    def autoscale(self):     pass
    def autoscale_None(self): pass
    def to_rgba(self, x, alpha=None, bytes=False, norm=True):
        """Map scalar values through (norm → cmap), matching upstream."""
        arr = _np.asarray(x, dtype=float)
        if norm and self.norm is not None:
            arr = self.norm(arr)
        elif norm:
            from matplotlib.colors import Normalize
            vmin, vmax = getattr(self, '_clim', (None, None))
            if vmin is None: vmin = float(_np.nanmin(arr))
            if vmax is None: vmax = float(_np.nanmax(arr))
            arr = Normalize(vmin=vmin, vmax=vmax)(arr)
        cmap = self.cmap
        if isinstance(cmap, str):
            from matplotlib.cm import get_cmap
            cmap = get_cmap(cmap)
        if cmap is not None:
            try: return cmap(arr, alpha=alpha, bytes=bytes)
            except Exception: pass
        return _np.stack([arr, arr, arr, _np.ones_like(arr)], axis=-1)

    def get_paths(self):
        return [seg for level_segs in self.allsegs for seg in level_segs]
    def remove(self):        pass
    def draw(self, renderer): pass


class QuadContourSet(ContourSet):
    pass


class ClabelText:
    pass


# ─── Added: missing public names from upstream contour.py ──────────


class ContourLabeler:
    """Mixin providing ``clabel`` to :class:`ContourSet`. Real matplotlib
    splits the labelling code into this class; the shim already exposes
    ``clabel`` on ContourSet but we still surface the symbol so callers
    that do ``isinstance(contours, ContourLabeler)`` succeed.
    """

    def clabel(self, levels=None, *, fontsize=None, inline=True, inline_spacing=5,
               fmt=None, colors=None, use_clabeltext=False, manual=False,
               rightside_up=True, zorder=None):
        # ContourSet.clabel already exists; this is the upstream-level
        # signature. Defer to ContourSet.clabel when present.
        if hasattr(self, '__contour_set_clabel__'):
            return self.__contour_set_clabel__(levels=levels)
        return []

    def labels(self, inline, inline_spacing):
        return []

    def add_label(self, x, y, rotation, lev, cvalue):
        return None

    def get_label_width(self, lev, fmt, fsize):
        return float(len(str(lev)) * (fsize or 10) * 0.6)


# Cannot mutate ContourSet.__bases__ at runtime (CPython rejects the
# assignment because Artist has a different layout). Register
# ContourSet / QuadContourSet as virtual subclasses of ContourLabeler
# via ABCMeta — isinstance(cs, ContourLabeler) still resolves correctly.
import abc as _abc
ContourLabeler = _abc.ABCMeta('ContourLabeler', (object,),
                               dict(ContourLabeler.__dict__))
ContourLabeler.register(ContourSet)
ContourLabeler.register(QuadContourSet)
# Also copy the clabel/labels/add_label methods onto ContourSet so they
# can actually be called on an instance.
for _name in ('labels', 'add_label', 'get_label_width'):
    if not hasattr(ContourSet, _name):
        setattr(ContourSet, _name, ContourLabeler.__dict__[_name])


