def _cs_find_nearest_contour(self, x, y, indices=None, pixel=True):
    """Return ``(con_idx, seg_idx, idx, xmin, ymin, dist)`` for the
    contour vertex closest to ``(x, y)``. Walks each segment in
    :attr:`allsegs` and computes Euclidean distance directly.
    """
    import math
    segs_per_level = self._allsegs if hasattr(self, '_allsegs') and self._allsegs \
                     else getattr(self, 'allsegs', [])
    if not segs_per_level:
        return None
    levels = range(len(segs_per_level)) if indices is None else indices
    best = None
    for con_idx in levels:
        segs = segs_per_level[con_idx]
        for seg_idx, seg in enumerate(segs):
            for idx, (px, py) in enumerate(seg):
                d = math.hypot(px - x, py - y)
                if best is None or d < best[5]:
                    best = (con_idx, seg_idx, idx, px, py, d)
    return best
def _cs_legend_elements(self, variable_name='x', str_format=str):
    """Return (handles, labels) the way :func:`Axes.legend` expects —
    one proxy per contour level. Filled contours produce Rectangle
    proxies; line contours produce Line2D proxies.
    """
    from matplotlib.lines import Line2D
    from matplotlib.patches import Rectangle
    levels = list(self.cvalues or self.levels)
    if not levels:
        return [], []
    # Resolve per-level colours.
    cmap = self.cmap
    if isinstance(cmap, str):
        try:
            from matplotlib.cm import get_cmap
            cmap = get_cmap(cmap)
        except Exception:
            cmap = None
    if cmap is not None and len(levels) > 1:
        positions = _np.linspace(0, 1, len(levels))
        colors = [cmap(p) for p in positions]
    elif self.colors is not None:
        if isinstance(self.colors, (list, tuple)):
            colors = list(self.colors)
            # Stretch/truncate to match level count.
            colors = colors * (len(levels) // len(colors) + 1)
            colors = colors[:len(levels)]
        else:
            colors = [self.colors] * len(levels)
    else:
        colors = ['C0'] * len(levels)
    handles = []
    labels = []
    for lev, col in zip(levels, colors):
        if self.filled:
            h = Rectangle((0, 0), 1, 1, facecolor=col, edgecolor='none',
                          alpha=self.alpha)
        else:
            h = Line2D([0], [0], color=col, linewidth=self.linewidths or 1.5,
                       alpha=self.alpha)
        handles.append(h)
        labels.append(f'${variable_name} = {str_format(lev)}$')
    return handles, labels
def _cs_get_alpha(self):    return self._alpha
def _cs_set_alpha(self, a): self._alpha = a

ContourSet.find_nearest_contour = _cs_find_nearest_contour
ContourSet.legend_elements      = _cs_legend_elements
ContourSet.get_alpha            = _cs_get_alpha
ContourSet.set_alpha            = _cs_set_alpha


