# ─── Real ContourSet helpers ────────────────────────────────────────


def _cs_remove(self):
    """Drop this contour from its parent Axes if registered."""
    if self.axes is not None and hasattr(self.axes, 'collections'):
        try:
            self.axes.collections.remove(self)
        except (ValueError, AttributeError):
            pass

ContourLabeler.remove = _cs_remove

# ``tcolors`` / ``tlinewidths`` are upstream's per-level color/width
# arrays. Compute them lazily so callers polling the attribute get a
# real array — not a no-op method.
def _cs_tcolors(self):
    levels = list(self.cvalues or self.levels)
    if not levels: return []
    cmap = self.cmap
    if isinstance(cmap, str):
        try:
            from matplotlib.cm import get_cmap
            cmap = get_cmap(cmap)
        except Exception: cmap = None
    if cmap is not None and len(levels) > 1:
        return [cmap(p) for p in _np.linspace(0, 1, len(levels))]
    if self.colors is not None:
        cols = list(self.colors) if isinstance(self.colors, (list, tuple)) else [self.colors]
        return (cols * (len(levels) // len(cols) + 1))[:len(levels)]
    return ['C0'] * len(levels)

def _cs_tlinewidths(self):
    levels = list(self.cvalues or self.levels)
    if not levels: return []
    lw = self.linewidths if self.linewidths is not None else 1.5
    if hasattr(lw, '__iter__') and not isinstance(lw, str):
        lws = list(lw)
        return (lws * (len(levels) // len(lws) + 1))[:len(levels)]
    return [float(lw)] * len(levels)

ContourSet.tcolors      = property(_cs_tcolors)
ContourSet.tlinewidths  = property(_cs_tlinewidths)
